<?php
require __DIR__.'/../config/app.php';
require_role('admin');
$action=(string)($_GET['action']??'');$id=(int)($_GET['id']??0);$error='';$event=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_check();$postAction=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
    try{
        if($postAction==='delete'){
            $q=db()->prepare('DELETE FROM cultural_activities WHERE id=?');$q->execute([$id]);
            flash($q->rowCount()?'Cultural activity deleted.':'Activity not found.');go('admin/cultural.php');
        }
        $title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$date=(string)($_POST['activity_date']??'');$venue=trim((string)($_POST['venue']??''));
        $validDate=DateTime::createFromFormat('Y-m-d',$date);
        if($title===''||mb_strlen($title)>190||$date===''||!$validDate||$validDate->format('Y-m-d')!==$date||$venue===''||mb_strlen($venue)>190)throw new RuntimeException('Enter a valid activity name, date, and venue.');
        if($id){$q=db()->prepare('UPDATE cultural_activities SET title=?,description=?,activity_date=?,venue=? WHERE id=?');$q->execute([$title,$description,$date,$venue,$id]);if(!$q->rowCount()){$check=db()->prepare('SELECT id FROM cultural_activities WHERE id=?');$check->execute([$id]);if(!$check->fetchColumn())throw new RuntimeException('Activity not found.');}flash('Cultural activity updated.');}
        else{db()->prepare('INSERT INTO cultural_activities(title,description,activity_date,venue) VALUES(?,?,?,?)')->execute([$title,$description,$date,$venue]);flash('Cultural activity created.');}
        go('admin/cultural.php');
    }catch(Throwable $t){$error=$t instanceof RuntimeException?$t->getMessage():'Could not save the cultural activity.';$action=$id?'edit':'create';$event=['id'=>$id,'title'=>$title??'','description'=>$description??'','activity_date'=>$date??'','venue'=>$venue??''];}
}
if($action==='edit'&&$id&&!$event){try{$q=db()->prepare('SELECT * FROM cultural_activities WHERE id=?');$q->execute([$id]);$event=$q->fetch();if(!$event){flash('Activity not found.','error');go('admin/cultural.php');}}catch(Throwable $t){$error='Could not load the activity.';}}
$creating=$action==='create';$editing=$creating||$action==='edit';
$search=trim((string)($_GET['q']??''));$rows=[];try{$q=db()->prepare('SELECT c.id,c.title,c.description,c.activity_date,c.venue,COUNT(r.user_id) registrations FROM cultural_activities c LEFT JOIN activity_registrations r ON r.activity_id=c.id WHERE (?=\'\' OR c.title LIKE ? OR c.venue LIKE ?) GROUP BY c.id ORDER BY c.activity_date DESC');$term='%'.$search.'%';$q->execute([$search,$term,$term]);$rows=$q->fetchAll();}catch(Throwable $t){$error=$error?:'Could not load cultural activities.';}if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="eventhub-cultural-activities-'.date('Ymd').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Activity','Date','Venue','Registrations']);foreach($rows as $r)fputcsv($out,[$r['title'],$r['activity_date'],$r['venue'],$r['registrations']]);fclose($out);exit;}
$perPage=25;$totalRecords=count($rows);$totalPages=(int)ceil($totalRecords/$perPage);$currentPage=max(1,min($totalPages?:1,(int)($_GET['page']??1)));$rows=array_slice($rows,($currentPage-1)*$perPage,$perPage);$pageTitle=$creating?'Add Cultural Activity':($editing?'Edit Cultural Activity':'Cultural Activities');$bodyClass='dashboard-page admin-page';$activePage='cultural';$adminSection='cultural';require __DIR__.'/../includes/header.php';
?><div class="dash-layout admin-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content admin-events-page"><header class="admin-page-heading"><div><span class="admin-eyebrow">CAMPUS CULTURE</span><h1><?=$editing?e($pageTitle):'Cultural Activities'?></h1><p><?=$editing?'Create or update a cultural activity for students.':'Manage campus activities and track student registrations.'?></p></div><?php if(!$editing):?><a class="btn primary" href="<?=url('admin/cultural.php?action=create')?>">Add Activity</a><?php endif;?></header><?php require __DIR__.'/section-nav.php';?><?php if(!$editing):?><section class="admin-work-card"><form method="get" class="admin-report-filters"><input name="q" value="<?=e($search)?>" placeholder="Search activities or venue"><button class="btn primary">Search</button><a class="btn outline" href="<?=url('admin/cultural.php?'.http_build_query(['q'=>$search,'export'=>'csv']))?>">Export CSV</a></form></section><?php endif;?><?php if($error):?><div class="inline-error"><?=e($error)?></div><?php endif;?>
<?php if($editing):?><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('music')?></span><div><h2>Activity details</h2><p>Add the date and location students need to participate.</p></div></div><form method="post" class="form-card admin-event-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=e((string)($event['id']??''))?>"><input type="hidden" name="action" value="save"><div class="admin-form-grid"><label>Activity name<input required maxlength="190" name="title" value="<?=e($event['title']??'')?>" placeholder="e.g. Garba Night"></label><label>Date<input required type="date" name="activity_date" value="<?=e($event['activity_date']??'')?>"></label><label>Venue<input required maxlength="190" name="venue" value="<?=e($event['venue']??'')?>" placeholder="Campus location"></label><label class="admin-form-wide">Description<textarea name="description" rows="4" placeholder="Share activity details..."><?=e($event['description']??'')?></textarea></label></div><div class="admin-form-actions"><a class="btn outline" href="<?=url('admin/cultural.php')?>">Cancel</a><button class="btn primary" type="submit"><?=$creating?'Create Activity':'Save Changes'?></button></div></form></section><?php else:?><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('music')?></span><div><h2>All activities <span class="admin-count"><?=count($rows)?></span></h2><p>Cultural activities and current participant registrations.</p></div></div><?php if($rows):?><div class="table-wrap admin-table-wrap"><table><thead><tr><th>Activity</th><th>Date</th><th>Venue</th><th>Registrations</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['title'])?></strong><?php if($r['description']):?><small><?=e(mb_strimwidth($r['description'],0,100,'…'))?></small><?php endif;?></td><td><?=date('d M Y',strtotime($r['activity_date']))?></td><td><?=e($r['venue'])?></td><td><a class="admin-count" href="<?=url('admin/activity-registrations.php?id='.$r['id'])?>"><?=(int)$r['registrations']?> · View</a></td><td><div class="admin-row-actions"><a href="<?=url('admin/cultural.php?action=edit&id='.$r['id'])?>">Edit</a><form class="inline-form" method="post" onsubmit="return confirm('Delete this activity and its registrations?')"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="text-button">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">No cultural activities yet. Add an activity to get started.</div><?php endif;?></section><?php endif;?><?php if(!$editing)require __DIR__.'/../includes/admin-pagination.php';?></main></div><?php require __DIR__.'/../includes/footer.php';
